#include "PCH.h"

#include "InputSink.h"

#include "core/Config.h"
#include "core/EventBus.h"
#include "core/LayerRegistry.h"
#include "core/Log.h"
#include "input/InputLayer.h"

// F4SEPlugin_Version (read by F4SE 0.7.x on NG/AE) is generated by the commonlibf4.plugin
// xmake rule from xmake.lua. This file adds F4SEPlugin_Query for F4SE 0.6.x on Old-Gen,
// which predates that export, and F4SEPlugin_Load, which every version calls.

namespace
{
	// Relative to the game's working directory; MO2's VFS maps our mod folder over Data/.
	constexpr auto kConfigPath = "Data/F4SE/Plugins/R-CATS.ini";

	rcats::Config g_config;
	rcats::EventBus g_bus;
	rcats::LayerRegistry g_layers;
	std::unique_ptr<rcats::input::InputLayer> g_input;

	REX::ELogLevel ToRexLevel(rcats::log::Level a_level) noexcept
	{
		using L = rcats::log::Level;
		switch (a_level) {
		case L::kTrace: return REX::ELogLevel::Trace;
		case L::kDebug: return REX::ELogLevel::Debug;
		case L::kInfo: return REX::ELogLevel::Info;
		case L::kWarn: return REX::ELogLevel::Warning;
		case L::kError: return REX::ELogLevel::Error;
		case L::kCritical:
		case L::kOff: return REX::ELogLevel::Critical;  // "off" is enforced by rcats::log itself
		}
		return REX::ELogLevel::Info;
	}

	// Core code logs through rcats::log; this routes it into CommonLibF4's log file in the
	// standard F4SE log folder (Documents\My Games\Fallout4\F4SE\R-CATS.log).
	void ForwardToRex(rcats::log::Level a_level, std::string_view a_message)
	{
		using L = rcats::log::Level;
		switch (a_level) {
		case L::kTrace: REX::TRACE("{}", a_message); break;
		case L::kDebug: REX::DEBUG("{}", a_message); break;
		case L::kInfo: REX::INFO("{}", a_message); break;
		case L::kWarn: REX::WARN("{}", a_message); break;
		case L::kError: REX::ERROR("{}", a_message); break;
		case L::kCritical: REX::CRITICAL("{}", a_message); break;
		case L::kOff: break;
		}
	}

	std::string_view RuntimeName() noexcept
	{
		if (REX::FModule::IsRuntimeOG()) return "Old-Gen";
		if (REX::FModule::IsRuntimeNG()) return "Next-Gen";
		if (REX::FModule::IsRuntimeAE()) return "Anniversary Edition";
		return "unknown runtime";
	}

	bool InstallInput()
	{
		g_input = std::make_unique<rcats::input::InputLayer>(g_config.input, g_bus);
		// The PlayerControls vtable is static data, so it can be patched right away. If it
		// can't be (or HookPlayerControls = 0), OnMessage attaches the MenuControls fallback.
		if (g_config.input.hookPlayerControls) {
			if (!rcats::plugin::InstallPlayerControlsHook(*g_input)) {
				rcats::log::Warn("Input: falling back to the MenuControls handler (misses the right trigger in gameplay)");
			}
		} else {
			rcats::log::Info("Input: PlayerControls hook disabled by config; using the MenuControls handler");
		}
		return true;
	}

	void OnMessage(F4SE::MessagingInterface::Message* a_msg)
	{
		if (!a_msg) {
			return;
		}
		rcats::log::Debug("F4SE message type {}", a_msg->type);
		const auto attachInput = [](std::string_view a_when) {
			if (g_input && g_layers.IsActive(rcats::LayerId::kInput)) {
				rcats::plugin::RegisterInputSink(*g_input, a_when);
			}
		};
		switch (a_msg->type) {
		case F4SE::MessagingInterface::kInputLoaded:
			attachInput("input loaded");
			break;
		case F4SE::MessagingInterface::kGameDataReady:
			rcats::log::Info("Game data ready");
			// Fallback: on AE 1.11.240 / F4SE 0.7.9 kInputLoaded never reached us (first
			// in-game test, 2026-11-06), so attach here if it hasn't happened yet.
			// MenuControls exists long before game data finishes loading.
			attachInput("game data ready");
			break;
		default:
			break;
		}
	}
}

F4SE_PLUGIN_QUERY(const F4SE::QueryInterface* a_f4se, F4SE::PluginInfo* a_info)
{
	a_info->infoVersion = F4SE::PluginInfo::kVersion;
	a_info->name = "R-CATS";
	a_info->version = 1;

	// Logging isn't up until Load, so just refuse quietly where we can't run.
	return !a_f4se->IsEditor();
}

F4SE_PLUGIN_LOAD(const F4SE::LoadInterface* a_f4se)
{
	// Config first, so its LogLevel applies from the very first line; its warnings are
	// held and written once logging exists.
	auto loaded = rcats::LoadConfig(kConfigPath);
	g_config = std::move(loaded.config);

	F4SE::Init(a_f4se, { .logLevel = ToRexLevel(g_config.logLevel) });

	rcats::log::SetSink(&ForwardToRex);
	rcats::log::SetLevel(g_config.logLevel);

	rcats::log::Info("{} v{} loading on Fallout 4 {} ({}), F4SE {}",
		F4SE::GetPluginName(), F4SE::GetPluginVersion().string(),
		F4SE::GetRuntimeVersion().string(), RuntimeName(), F4SE::GetF4SEVersion().string());

	for (const auto& warning : loaded.warnings) {
		rcats::log::Warn("Config: {}", warning);
	}

	g_layers.Register(rcats::LayerId::kInput, &InstallInput);
	g_layers.InstallAll(g_config);

	const auto messaging = F4SE::GetMessagingInterface();
	if (!messaging || !messaging->RegisterListener(&OnMessage)) {
		rcats::log::Error("Could not register for F4SE messages; engine-side layers will not attach");
	}

	rcats::log::Info("Load complete");
	return true;
}
